// Illustrated accessory layers share the same anchors for fitting previews and gameplay.
export function accessoryAnchors(gender,row=0){const male=gender==='male',side=row>1;return{male,back:row===1,side,headY:male?13:12,eyeY:side?76:male?75:71,eyes:side?[row===2?37:85]:male?[48,79]:[56,89],neck:male?100:95,waist:male?138:122};}
export function drawAccessories(ctx,{gender,row,col=0,outfit:o,headCenter=64,drift=0}){const a=accessoryAnchors(gender,row),{back,side,headY,eyeY,eyes,neck,waist}=a,ink='#725951',sway=col?Math.sin(col*Math.PI/3)*.8:0;
 ctx.save();ctx.translate(drift,0);ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=.9;
 const grad=(x,y,w,h,light,base,dark)=>{const g=ctx.createLinearGradient(x,y,x+w,y+h);g.addColorStop(0,light);g.addColorStop(.5,base);g.addColorStop(1,dark);return g;};
 const line=(points,color=ink,width=.9)=>{ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();};
 function panel(x,y,w,h,r,colors){ctx.fillStyle=grad(x,y,w,h,...colors);ctx.strokeStyle=ink;ctx.lineWidth=.9;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();ctx.stroke();ctx.strokeStyle='#fff5dc77';ctx.lineWidth=.6;ctx.beginPath();ctx.roundRect(x+1.6,y+1.6,w-3.2,h-3.2,Math.max(1,r-1));ctx.stroke();}
 function stitches(x,y,w,h){ctx.save();ctx.setLineDash([1.2,1.3]);ctx.strokeStyle='#fff2d4a6';ctx.lineWidth=.55;ctx.strokeRect(x+2,y+2,w-4,h-4);ctx.restore();}
 // Bags: contoured straps, gussets, pockets and warm metal hardware.
 if(o.bag==='backpack'){if(row===0){line([[48,neck+4],[49,waist-1]],'#627c65',3);line([[80,neck+4],[79,waist-1]],'#627c65',3);line([[48,neck+4],[49,waist-1]],'#c4d7b1',1.2);line([[80,neck+4],[79,waist-1]],'#c4d7b1',1.2);}else{const x=side?(row===2?74:38):48,y=neck+5,w=side?17:33,h=33;if(side){line([[row===2?55:73,neck+4],[x+w/2,y+4]],'#637c65',2.5);line([[row===2?55:73,neck+4],[x+w/2,y+4]],'#cfddbd',.8);}line([[x+w*.3,y],[x+w*.3,y-4],[x+w*.7,y-4],[x+w*.7,y]],'#6e866c',1.4);panel(x,y,w,h,6,['#d1dec2','#aebf9b','#809879']);panel(x+3,y+18,w-6,11,3,['#c6d4b7','#a4b997','#809b7a']);line([[x+4,y+19],[x+w-4,y+19]],'#667e61',.7);ctx.fillStyle='#d9c396';ctx.fillRect(x+w-6,y+18,1.6,3);stitches(x,y,w,h);}}
 if(o.bag==='crossbody'){const x=(back?side?65:73:side?row===2?34:76:76)+sway,y=waist-11,w=side?15:20;line([[side?(row===2?66:53):47,neck+3],[x+8,y+2]],'#80614e',2.4);line([[side?(row===2?66:53):47,neck+3],[x+8,y+2]],'#d0b397',.8);panel(x,y,w,17,4,['#ddc1a4','#bd9879','#946f58']);ctx.fillStyle=grad(x,y,w,8,'#ead5bb','#c8a78b','#a08065');ctx.beginPath();ctx.roundRect(x+.6,y+.6,w-1.2,7,3);ctx.fill();line([[x+1,y+7],[x+w-1,y+7]],'#8d6c56',.7);panel(x+w/2-2,y+5,4,4,1,['#fff2c9','#cfb278','#a48853']);stitches(x,y,w,17);}
 if(o.bag==='tote'){const x=(side?(row===2?36:76):back?38:79)+sway,y=waist-10,w=19;ctx.strokeStyle='#a28b70';ctx.lineWidth=1.8;ctx.beginPath();ctx.moveTo(x+4,y+1);ctx.bezierCurveTo(x+4,y-13,x+15,y-13,x+15,y+1);ctx.stroke();panel(x,y,w,25,3,['#fff5df','#e5d6b9','#bdac91']);stitches(x,y,w,25);line([[x+w-3,y+3],[x+w-3,y+22]],'#ac977c66',1);ctx.fillStyle='#b6bda1';ctx.beginPath();ctx.ellipse(x+10,y+13,3,5,-.4,0,Math.PI*2);ctx.fill();line([[x+9,y+17],[x+11,y+9]],'#789576',.7);}
 // Glasses are fitted to the eyes rather than the hairline.
 if(o.accessory==='glasses'){if(back){line([[35,eyeY-3],[40,eyeY]],'#8d7563',1);line([[91,eyeY],[96,eyeY-3]],'#8d7563',1);}else{for(const x of eyes){ctx.fillStyle='#fff8df18';ctx.strokeStyle='#866c55';ctx.lineWidth=1.15;ctx.beginPath();ctx.ellipse(x,eyeY,side?7:9,8.3,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#fff8e699';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(x-4,eyeY-4);ctx.lineTo(x-1,eyeY-6);ctx.stroke();}if(!side){ctx.strokeStyle='#866c55';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(eyes[0]+9,eyeY-1);ctx.quadraticCurveTo((eyes[0]+eyes[1])/2,eyeY-4,eyes[1]-9,eyeY-1);ctx.stroke();line([[eyes[0]-9,eyeY-2],[eyes[0]-13,eyeY-5]],'#866c55',.9);line([[eyes[1]+9,eyeY-2],[eyes[1]+13,eyeY-5]],'#866c55',.9);}else line([[eyes[0]+(row===2?7:-7),eyeY-2],[row===2?55:68,eyeY-5]],'#866c55',1);}}
 if(o.accessory==='scarf'){panel(52,neck-2,25,7,3,['#eed1b6','#d3aa8f','#af846f']);line([[54,neck+1],[74,neck+1]],'#fff3d266',.8);if(!back){const x=side?(row===2?52:72):68;panel(x,neck+3,7,16,2,['#e2bca2','#c99a82','#a87e6c']);for(let y=neck+6;y<neck+18;y+=4)line([[x+1,y],[x+6,y]],'#f2dac1bb',.65);for(let i=1;i<7;i+=2)line([[x+i,neck+18],[x+i-.5,neck+21]],'#b2846e',.7);}}
 if(o.accessory==='heart'&&!back){const x=side?(row===2?52:75):64;ctx.strokeStyle='#bca16f';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(x-8,neck+1);ctx.quadraticCurveTo(x,neck+15,x+8,neck+1);ctx.stroke();ctx.fillStyle=grad(x-3,neck+9,6,7,'#f6cfca','#d68e9c','#a86e80');ctx.strokeStyle='#a87480';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(x,neck+16);ctx.bezierCurveTo(x-9,neck+11,x-3,neck+5,x,neck+10);ctx.bezierCurveTo(x+3,neck+5,x+9,neck+11,x,neck+16);ctx.fill();ctx.stroke();line([[x-2,neck+10],[x-1,neck+9]],'#fff7eccc',.7);}
 // Hats follow the head anchor, with shaped crowns rather than flat rectangles.
 const hc=headCenter,hy=headY;
 if(o.hat==='beret'){ctx.fillStyle=grad(hc-35,hy-3,70,30,'#f0c7cf','#d59eaf','#ad778b');ctx.strokeStyle='#8f6376';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(hc-35,hy+19);ctx.bezierCurveTo(hc-39,hy-5,hc+31,hy-12,hc+37,hy+12);ctx.quadraticCurveTo(hc+36,hy+24,hc-35,hy+19);ctx.fill();ctx.stroke();ctx.strokeStyle='#fbe5d777';ctx.beginPath();ctx.moveTo(hc-28,hy+8);ctx.bezierCurveTo(hc-12,hy-4,hc+18,hy-3,hc+28,hy+7);ctx.stroke();line([[hc-30,hy+19],[hc+29,hy+19]],'#ac7688',2.2);line([[hc+7,hy-3],[hc+9,hy-8]],'#a56c80',2);}
 if(o.hat==='cap'){ctx.fillStyle=grad(hc-34,hy-3,68,30,'#d0e5ec','#a5c5d7','#789db8');ctx.strokeStyle='#6f8fa6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(hc-34,hy+24);ctx.bezierCurveTo(hc-35,hy-10,hc+34,hy-10,hc+34,hy+24);ctx.closePath();ctx.fill();ctx.stroke();line([[hc,hy-2],[hc,hy+22]],'#e3f0ec88',.7);line([[hc-16,hy+1],[hc-20,hy+22]],'#7198b166',.7);line([[hc+16,hy+1],[hc+20,hy+22]],'#7198b166',.7);ctx.fillStyle=grad(hc-37,hy+20,74,12,'#bed6e1','#8db2c8','#668ca8');ctx.beginPath();ctx.ellipse(side?hc+(row===2?-24:24):hc,hy+24,side?25:37,5.5,side?(row===2?-.12:.12):0,0,Math.PI*2);ctx.fill();ctx.stroke();if(!back&&!side)panel(hc-4,hy+10,8,7,2,['#f8eed8','#dfdbbd','#b7c1ad']);}
 if(o.hat==='straw'){ctx.fillStyle=grad(hc-45,hy+17,90,15,'#fff0c1','#e4c88f','#b99c66');ctx.strokeStyle='#9b825b';ctx.lineWidth=.9;ctx.beginPath();ctx.ellipse(hc,hy+24,45,8,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#b99f6f77';ctx.beginPath();ctx.ellipse(hc,hy+24,40,5.5,0,0,Math.PI*2);ctx.stroke();panel(hc-25,hy-1,50,27,9,['#f6e5b4','#dec48f','#b99c6a']);ctx.save();ctx.beginPath();ctx.roundRect(hc-24,hy,48,25,8);ctx.clip();for(let y=hy+3;y<hy+23;y+=3)line([[hc-25,y],[hc+25,y]],'#a98d5c44',.6);for(let x=hc-22;x<hc+23;x+=4)line([[x,hy],[x+8,hy+25]],'#fff7d566',.6);ctx.restore();panel(hc-24,hy+18,48,5,2,['#c89e80','#b18268','#8d6753']);}
 if(o.hat==='bow'){ctx.strokeStyle='#a9798b';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(hc,hy+17,34,10,0,Math.PI,Math.PI*2);ctx.stroke();for(const sideSign of [-1,1]){ctx.fillStyle=grad(hc-30,hy-8,60,30,'#f7d2d8','#dda9ba','#b87c96');ctx.strokeStyle='#a7758b';ctx.lineWidth=.9;ctx.beginPath();ctx.moveTo(hc,hy+10);ctx.bezierCurveTo(hc+sideSign*34,hy-10,hc+sideSign*37,hy+28,hc,hy+14);ctx.fill();ctx.stroke();line([[hc+sideSign*5,hy+11],[hc+sideSign*23,hy+7]],'#fff1e577',.8);line([[hc+sideSign*4,hy+13],[hc+sideSign*23,hy+17]],'#a9758c55',.7);}panel(hc-4,hy+7,8,9,3,['#efc5d0','#ca8ea6','#a96c87']);}
 if(o.accessory==='flower'){const x=back?hc-30:row===2?40:hc+30,y=hy+37;line([[x-5,y+6],[x+5,y-5]],'#a89671',1);for(let n=0;n<5;n++){const angle=n*Math.PI*2/5;ctx.save();ctx.translate(x+Math.cos(angle)*3.6,y+Math.sin(angle)*3.6);ctx.rotate(angle);ctx.fillStyle=grad(-3,-3,6,6,'#fff7de','#ecd4b1','#d1b091');ctx.strokeStyle='#c3ab8d';ctx.lineWidth=.45;ctx.beginPath();ctx.ellipse(0,0,3.2,2.4,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}ctx.fillStyle='#d6af68';ctx.beginPath();ctx.arc(x,y,2.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff5d1';ctx.beginPath();ctx.arc(x-.5,y-.6,.75,0,Math.PI*2);ctx.fill();}
 ctx.restore();}
